referenceFixTemplate:
#include <iostream>
using namespace std;

template <typename... Args>
int countAll(Args... args) {
    return sizeof...(args);
}

template <typename T, typename... Rest>
int firstPlusCount(T first, Rest... rest) {
    return first + countAll(rest...);
}

int main() {
    cout << firstPlusCount({w1}, {w2}, 4) << endl;
    return 0;
}
